const W = 128;
const H = 128;

// The toast set's warm palette; 9 is the orange inner ear. Same colours in both themes —
// the dark theme adds a greige rim around the silhouette instead.
const PALETTE: Record<number, string | null> = {
    0: null,
    1: '#fbfaf8',
    2: '#e8e5e0',
    3: '#c3bdb6',
    4: '#8f8a84',
    5: '#5f5e5c',
    6: '#2e2f30',
    7: '#1b1c1c',
    8: '#0a0a09',
    9: '#f57626',
};

interface PixelPetHeadProps {
    scale?: number;
    className?: string;
}

export default function CatronautHappy({ scale = 3, className }: PixelPetHeadProps) {
    const canvasRef = useRef<HTMLCanvasElement>(null);
    const rafRef = useRef<number>(0);

    useEffect(() => {
        const canvas = canvasRef.current;
        if (!canvas) return;
        const ctx = canvas.getContext('2d');
        if (!ctx) return;
        ctx.imageSmoothingEnabled = false;

        const PAD = 6;
        const open = themedSprite(OPEN_GRID, PALETTE);
        const closed = themedSprite(CLOSED_GRID, PALETTE);
        const reduced = prefersReducedMotion();

        let t = 0;
        let blinkTimer = 0;
        const BLINK_EVERY = 200;
        const BLINK_LEN = 8;

        const render = () => {
            const blinking = !reduced && blinkTimer < BLINK_LEN;
            const bob = reduced ? 0 : Math.round(Math.sin(t * 0.045) * 1.6);
            const sprite = blinking ? closed : open;

            ctx.clearRect(0, 0, canvas.width, canvas.height);
            ctx.drawImage(isDarkTheme() ? sprite.dark : sprite.light, 0, PAD + bob);
        };

        if (reduced) {
            render();
            return;
        }

        const frame = () => {
            t += 1;
            blinkTimer += 1;
            if (blinkTimer > BLINK_EVERY) blinkTimer = 0;
            render();
            rafRef.current = requestAnimationFrame(frame);
        };

        frame();
        return () => cancelAnimationFrame(rafRef.current);
    }, []);

    return (
        <canvas
            ref={canvasRef}
            width={W}
            height={H + 12}
            className={className}
            style={{
                width: W * scale,
                height: (H + 12) * scale,
                maxWidth: 'none',
                maxHeight: 'none',
                display: 'block',
                flexShrink: 0,
                boxSizing: 'content-box',
                imageRendering: 'pixelated',
            }}
        />
    );
}
